	@ParameterizedTest
	@ValueSource(strings = { "RESOURCE_LIMIT_REACHED", "UNSUPPORTED_SEMANTICS" })
	void receiptRetainsExplicitIncompleteCompletion(String completion) {
		QueryRoot root = new QueryRoot(join());
		root.setStringMetricPlanned("optimizer.cascadesApplied", "true");
		root.setStringMetricPlanned("optimizer.cascadesCompleteness", completion);
		root.setStringMetricPlanned("optimizer.pipelinePlanCacheHit", "false");
		root.setStringMetricPlanned("optimizer.cascadesPlanCacheHit", "false");

		PlanningReceipt receipt = PlanningReceipt.capture(root, true);
		assertEquals(PlanningPath.FRESH, receipt.path());
		assertEquals(completion, receipt.completion().name());
		assertThrows(IllegalStateException.class, receipt::requireComplete);
		assertThrows(IllegalStateException.class, () -> PlanningExpectation.COMPLETE.validate(receipt));
		PlanningExpectation.valueOf(completion).validate(receipt);
		PlanningExpectation.OBSERVE.validate(receipt);
	}

	@Test
	void standalonePlannerDoesNotClaimAnOuterCachePath() {
		String previousMode = System.setProperty(LmdbCascadesOptimizer.MODE_PROPERTY, "exact");
		try {
			LmdbStatementPatternCardinalitySource cardinalities = mock(LmdbStatementPatternCardinalitySource.class);
			when(cardinalities.estimateForPlanning(any(StatementPattern.class))).thenReturn(10.0d);
			LmdbEvaluationStatistics statistics = new LmdbEvaluationStatistics(
					null, null, null, null, null, cardinalities, new PackedPlanCache(16, 1));
			LmdbCascadesOptimizer optimizer = new LmdbCascadesOptimizer(statistics, false);
			var cold = optimizer.optimizeWithResult(new QueryRoot(join()), null, EmptyBindingSet.getInstance());
			assertNotNull(cold.cascadesPlan());
			assertFalse(cold.cascadesPlan().metrics().planCacheHit());
			PlanningReceipt fresh = PlanningReceipt.capture(cold.installedPlan(), true);
			assertEquals(PlanningPath.UNOBSERVED, fresh.path());
			assertEquals(PlanningCompletion.COMPLETE, fresh.completion());
			assertTrue(cold.cascadesPlan().metrics().workUnits() > 0L);
			assertTrue(fresh.workUnits().isEmpty());
			assertNotNull(fresh.selectedRule());
			PlanningExpectation.OBSERVE.validate(fresh);
			assertThrows(IllegalStateException.class, () -> PlanningExpectation.FRESH_COMPLETE.validate(fresh));
			assertThrows(IllegalStateException.class, () -> PlanningExpectation.CACHED_COMPLETE.validate(fresh));

			clearInvocations(cardinalities);
			var hot = optimizer.optimizeWithResult(new QueryRoot(join()), null, EmptyBindingSet.getInstance());
			assertNotNull(hot.cascadesPlan());
			assertTrue(hot.cascadesPlan().metrics().planCacheHit());
			verify(cardinalities, never()).estimateForPlanning(any(StatementPattern.class));
			PlanningReceipt cached = PlanningReceipt.capture(hot.installedPlan(), true);
			assertEquals(PlanningPath.UNOBSERVED, cached.path());
			assertEquals(PlanningCompletion.COMPLETE, cached.completion());
			assertEquals(0L, hot.cascadesPlan().metrics().workUnits());
			assertTrue(cached.workUnits().isEmpty());
			assertEquals(fresh.selectedRule(), cached.selectedRule());
			PlanningExpectation.OBSERVE.validate(cached);
			assertThrows(IllegalStateException.class, () -> PlanningExpectation.CACHED_COMPLETE.validate(cached));
			assertThrows(IllegalStateException.class, () -> PlanningExpectation.FRESH_COMPLETE.validate(cached));
		} finally {
			restore(LmdbCascadesOptimizer.MODE_PROPERTY, previousMode);
		}
	}

	@Test
	void pipelineCacheReceiptDoesNotAttributeStoredConstructionWork(@TempDir File dataDir) throws Exception {
		String previousMode = System.setProperty(LmdbCascadesOptimizer.MODE_PROPERTY, "exact");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setBackgroundRawSamplingEnabled(false);
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:a"), VF.createIRI("urn:p"), VF.createIRI("urn:b"));
				connection.add(VF.createIRI("urn:b"), VF.createIRI("urn:q"), VF.createIRI("urn:c"));
			}
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			var backing = store.getSailStore();
			try (SailSource source = backing.getExplicitSailSource().fork();
					SailDataset dataset = source.dataset(IsolationLevels.SNAPSHOT_READ)) {
				SailDatasetTripleTermSource triples = new SailDatasetTripleTermSource(backing.getValueFactory(),
						dataset);
				var statistics = backing.getEvaluationStatistics();
				EvaluationStrategy strategy = store.getEvaluationStrategyFactory()
						.createEvaluationStrategy(null, triples, statistics);
				LmdbQueryOptimizerPipeline pipeline = new LmdbQueryOptimizerPipeline(strategy, triples, statistics);
				TupleExpr cold = pipeline.optimize(new QueryRoot(join()), null, EmptyBindingSet.getInstance());
				assertEquals("false", cold.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"));
				assertTrue(cold.getDoubleMetricPlanned("optimizer.cascadesWorkUnits") > 0.0d);
				PlanningReceipt fresh = PlanningReceipt.capture(cold, true);
				assertEquals(PlanningPath.FRESH, fresh.path());
				assertEquals(PlanningCompletion.COMPLETE, fresh.completion());
				assertEquals(cold.getDoubleMetricPlanned("optimizer.cascadesWorkUnits"),
						fresh.workUnits().orElseThrow());
				PlanningExpectation.FRESH_COMPLETE.validate(fresh);

				// Time tracking is part of the outer pipeline cache key, but not the packed search key.
				strategy.setTrackTime(true);
				TupleExpr packed = pipeline.optimize(new QueryRoot(join()), null, EmptyBindingSet.getInstance());
				assertEquals("false", packed.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"));
				assertEquals("true", packed.getStringMetricPlanned("optimizer.cascadesPlanCacheHit"));
				PlanningReceipt innerHit = PlanningReceipt.capture(packed, true);
				assertEquals(PlanningPath.PACKED_CACHE, innerHit.path());
				assertEquals(PlanningCompletion.COMPLETE, innerHit.completion());
				assertEquals(packed.getDoubleMetricPlanned("optimizer.cascadesWorkUnits"),
						innerHit.workUnits().orElseThrow());
				assertEquals(fresh.selectedRule(), innerHit.selectedRule());
				PlanningExpectation.CACHED_COMPLETE.validate(innerHit);
				assertThrows(IllegalStateException.class, () -> PlanningExpectation.FRESH_COMPLETE.validate(innerHit));

				strategy.setTrackTime(false);
				TupleExpr hot = pipeline.optimize(new QueryRoot(join()), null, EmptyBindingSet.getInstance());
				assertEquals("true", hot.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"));
				assertEquals("true", hot.getStringMetricPlanned("optimizer.cascadesPlanCacheHit"));
				assertTrue(hot.getDoubleMetricPlanned("optimizer.cascadesWorkUnits") > 0.0d,
						"the retained plan still carries its construction work");
				PlanningReceipt receipt = PlanningReceipt.capture(hot, true);
				assertEquals(PlanningPath.PIPELINE_CACHE, receipt.path());
				assertEquals(PlanningCompletion.COMPLETE, receipt.completion());
				assertEquals(cold.getStringMetricPlanned("optimizer.cascadesRule"), receipt.selectedRule());
				assertTrue(receipt.searchNanos().isEmpty());
				assertTrue(receipt.workUnits().isEmpty());
				assertTrue(receipt.candidateEvaluations().isEmpty());
				PlanningExpectation.CACHED_COMPLETE.validate(receipt);
				try (var rows = strategy.precompile(hot).evaluate(EmptyBindingSet.getInstance())) {
					assertTrue(rows.hasNext());
					var row = rows.next();
					assertEquals(VF.createIRI("urn:a"), row.getValue("a"));
					assertEquals(VF.createIRI("urn:b"), row.getValue("b"));
					assertEquals(VF.createIRI("urn:c"), row.getValue("c"));
					assertFalse(rows.hasNext());
				}
			}
		} finally {
			try {
				repository.shutDown();
			} finally {
				restore(LmdbCascadesOptimizer.MODE_PROPERTY, previousMode);
			}
		}
	}

	@Test
	void fallbackAndUnobservedPlanningAreNotQualified() {
		String previousMode = System.setProperty(LmdbCascadesOptimizer.MODE_PROPERTY, "exact");
		try {
			var optimizer = new LmdbCascadesOptimizer(new EvaluationStatistics(), false);
			var fallback = optimizer.optimizeWithResult(new QueryRoot(new OpaqueTuple(join())), null,
					EmptyBindingSet.getInstance());
			assertNull(fallback.cascadesPlan());
			PlanningReceipt receipt = PlanningReceipt.capture(fallback.installedPlan(), true);
			assertEquals(PlanningCompletion.FALLBACK, receipt.completion());
			assertEquals(PlanningPath.UNOBSERVED, receipt.path());
			assertTrue(receipt.fallbackReason().contains("UnsupportedCascadesOperatorException"));
			assertThrows(IllegalStateException.class, receipt::requireComplete);
			PlanningExpectation.OBSERVE.validate(receipt);

			PlanningReceipt missing = PlanningReceipt.capture(new QueryRoot(join()), true);
			assertEquals(PlanningPath.UNOBSERVED, missing.path());
			assertEquals(PlanningCompletion.UNOBSERVED, missing.completion());
			assertThrows(IllegalStateException.class, missing::requireComplete);
			assertEquals(PlanningCompletion.UNOBSERVED, PlanningReceipt.capture(fallback.installedPlan(), false)
					.completion(), "a written-order plan is not a Cascades invocation");

			QueryRoot inconsistent = new QueryRoot(join());
			inconsistent.setStringMetricPlanned("optimizer.cascadesApplied", "true");
			inconsistent.setStringMetricPlanned("optimizer.cascadesCompleteness", "COMPLETE");
			inconsistent.setStringMetricPlanned("optimizer.pipelinePlanCacheHit", "true");
			inconsistent.setStringMetricPlanned("optimizer.cascadesPlanCacheHit", "false");
			PlanningReceipt contradictory = PlanningReceipt.capture(inconsistent, true);
			assertEquals(PlanningPath.UNOBSERVED, contradictory.path());
			assertThrows(IllegalStateException.class, contradictory::requireComplete);
		} finally {
			restore(LmdbCascadesOptimizer.MODE_PROPERTY, previousMode);
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "false", "true" })
	void missingOuterCacheMarkerDoesNotClaimAnObservedPath(String packedHit) {
		QueryRoot root = new QueryRoot(join());
		root.setStringMetricPlanned("optimizer.cascadesApplied", "true");
		root.setStringMetricPlanned("optimizer.cascadesCompleteness", "COMPLETE");
		root.setStringMetricPlanned("optimizer.cascadesPlanCacheHit", packedHit);
		root.setDoubleMetricPlanned("optimizer.cascadesWorkUnits", 42.0d);

		PlanningReceipt receipt = PlanningReceipt.capture(root, true);
		assertEquals(PlanningPath.UNOBSERVED, receipt.path(), "the outer-cache decision is absent");
		assertEquals(PlanningCompletion.COMPLETE, receipt.completion(),
				"the selected plan's completeness remains independently observable");
		assertTrue(receipt.workUnits().isEmpty(), "unattributed construction work is not current work");
		assertThrows(IllegalStateException.class, receipt::requireComplete);
		PlanningExpectation.OBSERVE.validate(receipt);
	}

