	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void uncachedPipelineMarksTheActualOuterCacheDecision(boolean staleHit, @TempDir File dataDir) throws Exception {
		String previousMode = System.setProperty(LmdbCascadesOptimizer.MODE_PROPERTY, "exact");
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setBackgroundRawSamplingEnabled(false));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:a"), VF.createIRI("urn:p"), VF.createIRI("urn:b"));
				connection.add(VF.createIRI("urn:b"), VF.createIRI("urn:q"), VF.createIRI("urn:c"));
			}
			var backing = store.getSailStore();
			try (SailSource source = backing.getExplicitSailSource().fork();
					SailDataset dataset = source.dataset(IsolationLevels.SNAPSHOT_READ)) {
				SailDatasetTripleTermSource triples = new SailDatasetTripleTermSource(backing.getValueFactory(),
						dataset);
				EvaluationStatistics statistics = new EvaluationStatistics(); // No store runtime or pipeline cache.
				EvaluationStrategy strategy = store.getEvaluationStrategyFactory()
						.createEvaluationStrategy(null, triples, statistics);
				LmdbQueryOptimizerPipeline pipeline = new LmdbQueryOptimizerPipeline(strategy, triples, statistics);
				QueryRoot input = new QueryRoot(join());
				if (staleHit) {
					input.setStringMetricPlanned("optimizer.pipelinePlanCacheHit", "true");
					input.getArg().setStringMetricPlanned("optimizer.pipelinePlanCacheHit", "true");
				}
				TupleExpr optimized = pipeline.optimize(input, null, EmptyBindingSet.getInstance());
				assertEquals("true", optimized.getStringMetricPlanned("optimizer.cascadesApplied"));
				assertEquals("COMPLETE", optimized.getStringMetricPlanned("optimizer.cascadesCompleteness"));
				assertEquals("false", optimized.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"));
				assertEquals("false", ((QueryRoot) optimized).getArg()
						.getStringMetricPlanned("optimizer.pipelinePlanCacheHit"));
				PlanningReceipt receipt = PlanningReceipt.capture(optimized, true);
				assertEquals(PlanningPath.FRESH, receipt.path());
				PlanningExpectation.FRESH_COMPLETE.validate(receipt);
				try (var rows = strategy.precompile(optimized).evaluate(EmptyBindingSet.getInstance())) {
					assertTrue(rows.hasNext());
					var row = rows.next();
					assertEquals(VF.createIRI("urn:a"), row.getValue("a"));
					assertEquals(VF.createIRI("urn:b"), row.getValue("b"));
					assertEquals(VF.createIRI("urn:c"), row.getValue("c"));
					assertFalse(rows.hasNext());
				}
			}
		} finally {
			try {
				repository.shutDown();
			} finally {
				restore(LmdbCascadesOptimizer.MODE_PROPERTY, previousMode);
			}
		}
	}

	@Test
	void preparedReceiptReportsTheActualPipelineCacheHit(@TempDir File dataDir) throws Exception {
		String previousMode = System.setProperty(LmdbCascadesOptimizer.MODE_PROPERTY, "exact");
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setBackgroundRawSamplingEnabled(false);
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				connection.add(VF.createIRI("urn:a"), VF.createIRI("urn:p"), VF.createIRI("urn:b"));
				connection.add(VF.createIRI("urn:b"), VF.createIRI("urn:q"), VF.createIRI("urn:c"));
				LmdbTestUtil.awaitBackgroundMaintenance(store, 30, TimeUnit.SECONDS);
				String query = "SELECT ?a ?b ?c WHERE { ?a <urn:p> ?b . ?b <urn:q> ?c }";
				try (LmdbBenchmarkQueryPlan cold = LmdbBenchmarkQueryPlan.prepare(store, connection, query, 0, true)) {
					assertEquals(PlanningPath.FRESH, cold.planningReceipt().path());
					assertEquals(PlanningCompletion.COMPLETE, cold.planningReceipt().completion());
				}
				try (LmdbBenchmarkQueryPlan hot = LmdbBenchmarkQueryPlan.prepare(store, connection, query, 0, true)) {
					hot.inspectCapturedOptimizedExpression(expression -> assertEquals("true",
							expression.getStringMetricPlanned("optimizer.pipelinePlanCacheHit")));
					assertEquals(PlanningPath.PIPELINE_CACHE, hot.planningReceipt().path());
					assertEquals(PlanningCompletion.COMPLETE, hot.planningReceipt().completion());
					assertTrue(hot.planningReceipt().workUnits().isEmpty());
					PlanningExpectation.CACHED_COMPLETE.validate(hot.planningReceipt());
					try (var rows = hot.evaluate()) {
						assertTrue(rows.hasNext());
						var row = rows.next();
						assertEquals(VF.createIRI("urn:a"), row.getValue("a"));
						assertEquals(VF.createIRI("urn:b"), row.getValue("b"));
						assertEquals(VF.createIRI("urn:c"), row.getValue("c"));
						assertFalse(rows.hasNext());
					}
				}
			}
		} finally {
			try {
				repository.shutDown();
			} finally {
				restore(LmdbCascadesOptimizer.MODE_PROPERTY, previousMode);
			}
		}
	}

	@Test
	void genericPreparationRecordsIncompleteSearchWithoutASecondOptimization(@TempDir File dataDir) throws Exception {
		String previousMode = System.setProperty(LmdbCascadesOptimizer.MODE_PROPERTY, "budgeted");
		String previousBudget = System.setProperty(LmdbCascadesOptimizer.BUDGET_PROPERTY, "1");
		String previousTimeout = System.setProperty(LmdbCascadesOptimizer.TIMEOUT_MILLIS_PROPERTY, "60000");
		LmdbStatementPatternCardinalitySource cardinalities = mock(LmdbStatementPatternCardinalitySource.class);
		when(cardinalities.estimateForPlanning(any(StatementPattern.class))).thenReturn(10.0d);
		var statistics = new LmdbEvaluationStatistics(null, null, null, null, null, cardinalities,
				new PackedPlanCache(16, 1));
		var optimizer = new LmdbCascadesOptimizer(statistics, false);
		AtomicInteger optimizations = new AtomicInteger();
		QueryOptimizerPipeline pipeline = () -> List.of((expression, dataset, bindings) -> {
			optimizations.incrementAndGet();
			optimizer.optimize(expression, dataset, bindings);
		});
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")
				.setNativeEvaluationEnabled(false)
				.setSketchEstimatorEnabled(false));
		store.getEvaluationStrategyFactory().setOptimizerPipeline(pipeline);
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				StringBuilder query = new StringBuilder("SELECT * WHERE { ");
				for (int index = 0; index < 4; index++) {
					connection.add(VF.createIRI("urn:n" + index), VF.createIRI("urn:p" + index),
							VF.createIRI("urn:n" + (index + 1)));
					query.append("?s")
							.append(index)
							.append(" <urn:p")
							.append(index)
							.append("> ?s")
							.append(index + 1)
							.append(" . ");
				}
				query.append('}');
				try (LmdbBenchmarkQueryPlan prepared = LmdbBenchmarkQueryPlan.prepare(store, connection,
						query.toString(), 0, false)) {
					PlanningReceipt receipt = prepared.planningReceipt();
					assertSame(receipt, prepared.planningReceipt());
					assertEquals(1, optimizations.get(), "reading the receipt must not optimize again");
					assertEquals(PlanningPath.UNOBSERVED, receipt.path());
					assertEquals(PlanningCompletion.BUDGET_EXHAUSTED, receipt.completion());
					assertNull(prepared.preparedPlanSnapshot(), "a receipt must not require rendered diagnostics");
					assertThrows(IllegalStateException.class, receipt::requireComplete);
					assertThrows(IllegalStateException.class,
							() -> PlanningExpectation.BUDGET_EXHAUSTED.validate(receipt));
					PlanningExpectation.OBSERVE.validate(receipt);
					try (var rows = prepared.evaluate()) {
						assertTrue(rows.hasNext());
						assertEquals(VF.createIRI("urn:n0"), rows.next().getValue("s0"));
						assertFalse(rows.hasNext());
					}
				}
			}
		} finally {
			try {
				repository.shutDown();
			} finally {
				restore(LmdbCascadesOptimizer.MODE_PROPERTY, previousMode);
				restore(LmdbCascadesOptimizer.BUDGET_PROPERTY, previousBudget);
				restore(LmdbCascadesOptimizer.TIMEOUT_MILLIS_PROPERTY, previousTimeout);
			}
		}
	}

	private static Join join() {
		Join join = new Join(pattern("a", "urn:p", "b"), pattern("b", "urn:q", "c"));
		PlanningGraphDomains.capture(join, PlanningGraphDomain.defaultGraph());
		return join;
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject),
				Var.of("_const_" + predicate, VF.createIRI(predicate), false, true),
				Var.of(object));
	}

	private static void restore(String name, String value) {
		if (value == null) {
			System.clearProperty(name);
		} else {
			System.setProperty(name, value);
		}
	}

	private static final class OpaqueTuple extends UnaryTupleOperator {
		private static final long serialVersionUID = 1L;

		private OpaqueTuple(TupleExpr argument) {
			super(argument);
		}

		@Override
		public <X extends Exception> void visit(QueryModelVisitor<X> visitor) throws X {
			visitor.meetOther(this);
		}
	}
